import 'package:flutter/material.dart';import 'package:sehatak/core/models/women/women_models.dart';import 'package:sehatak/core/services/women_service.dart';class WomenClinicDetailScreen extends StatelessWidget{final String clinicId;const WomenClinicDetailScreen({super.key,required this.clinicId});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل العيادة')),body:FutureBuilder<List<WomenClinic>>(future:WomenService().streamClinics(limit:50).first,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final x=s.data!.where((e)=>e.id==clinicId);if(x.isEmpty)return const Center(child:Text('العيادة غير موجودة'));final d=x.first;return ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.local_hospital,size:70,color:Color(0xFF9C27B0)),Text(d.name,textAlign:TextAlign.center,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text(d.type,textAlign:TextAlign.center),Text('العنوان: ${d.address}'),Text('الهاتف: ${d.phone}'),Text('التقييم: ${d.rating.toStringAsFixed(1)}')]);}));}}
